package run.ikaros.finance; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/finance/ledgers/{ledgerId}/scheduled-transactions") public class ScheduledTransactionController{private final ScheduledTransactionService service;public ScheduledTransactionController(ScheduledTransactionService s){service=s;}@PostMapping public Mono<ScheduledTransactionView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId,@Valid@RequestBody CreateScheduledTransactionRequest r){return service.create(a,ledgerId,r);}@GetMapping public Flux<ScheduledTransactionView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId){return service.list(a,ledgerId);}@PostMapping("/{id}/actions/enable")public Mono<ScheduledTransactionView> enable(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.setActive(a,id,true);}@PostMapping("/{id}/actions/disable")public Mono<ScheduledTransactionView> disable(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.setActive(a,id,false);}}
